<?php
require_once __DIR__.'/business-workflow.php';
function bizSaleGross(array $d,int $qty): ?int {if($d['amount_cents']===null)return null;$sold=(int)query('SELECT COALESCE(SUM(qty),0) FROM biz_sales WHERE delivery_id=?',[$d['id']])->fetchColumn();return (int)round(($sold+$qty)*(int)$d['amount_cents']/(int)$d['delivered'])-(int)round($sold*(int)$d['amount_cents']/(int)$d['delivered']);}
function bizLabel(array $p): string {return $p['ko'].' / '.$p['en'];}
function bizConsigned(string $code,string $category): bool {return ($code==='OK'&&$category!=='kimchi')||($code==='PT'&&$category!=='kimchi');}
function bizRate(mixed $v): int {if(!is_string($v)||!preg_match('/^\d{1,3}(?:\.\d{1,2})?$/D',$v)||(float)$v>100)throw new InvalidArgumentException('할인율은 0~100%입니다.');return (int)round((float)$v*100);}
function bizPrice(array $client,array $p): int {
 if(isset($p['amount_cents'])&&max((int)($p['delivered']??0),(int)($p['planned']??0))>0)return (int)round($p['amount_cents']/(($p['delivered']??0)>0?$p['delivered']:$p['planned']));
 if(isset($p['unit_cents']))return (int)$p['unit_cents'];
 $price=query('SELECT cents FROM biz_prices WHERE client_id=? AND product_id=?',[$client['id'],$p['id']])->fetchColumn();
 if($client['code']==='OK'&&$p['category']!=='kimchi')$price=$p['retail_cents'];
 elseif(!$client['code'])$price=$p['retail_cents'];
 if($price===false||$price===null)throw new InvalidArgumentException(bizLabel($p).' 단가를 먼저 등록하세요.');return (int)$price;
}
function bizAvailable(int $id): int {return (int)query('SELECT delivered-COALESCE((SELECT SUM(qty) FROM biz_sales WHERE delivery_id=d.id),0)-COALESCE((SELECT SUM(qty) FROM biz_returns WHERE delivery_id=d.id),0) FROM biz_deliveries d WHERE id=?',[$id])->fetchColumn();}
function bizClosed(int $client,string $day): void {if(query("SELECT invoice_id FROM biz_periods WHERE client_id=? AND ? BETWEEN start_day AND end_day",[$client,$day])->fetchColumn())throw new InvalidArgumentException('이미 정산한 기간입니다. 추가 판매는 인보이스 정정 절차가 필요합니다.');}
function bizIssue(int $client,string $start,string $end,string $kind,?string $delivery=null,int $staffCount=0,int $staffUnit=150): int {
 if($start>$end)throw new InvalidArgumentException('기간을 확인하세요.');$c=query('SELECT * FROM biz_clients WHERE id=?',[$client])->fetch();if(!$c)throw new InvalidArgumentException('거래처를 확인하세요.');
 if($delivery===null&&($prior=query('SELECT invoice_id FROM biz_periods WHERE client_id=? AND kind=? AND start_day=? AND end_day=?',[$client,$kind,$start,$end])->fetchColumn()))return (int)$prior;
 if($delivery===null){if(query('SELECT invoice_id FROM biz_periods WHERE client_id=? AND start_day<=? AND end_day>=?',[$client,$end,$start])->fetchColumn())throw new InvalidArgumentException('이미 정산한 기간과 겹칩니다. 기간을 확인하세요.');if($c['code']==='OK'&&((new DateTimeImmutable($start))->format('N')!=='1'||(new DateTimeImmutable($start))->modify('+6 days')->format('Y-m-d')!==$end))throw new InvalidArgumentException('OK Mart는 월요일부터 일요일까지 한 주를 선택하세요.');if($c['code']==='PT'&&((new DateTimeImmutable($start))->format('j')!=='1'||(new DateTimeImmutable($start))->format('Y-m-t')!==$end))throw new InvalidArgumentException('Popularitea는 한 달의 1일부터 말일까지 선택하세요.');}
 $rows=query('SELECT s.*,p.category,p.ko,p.en,p.pack,p.hst_bp FROM biz_sales s JOIN biz_deliveries d ON d.id=s.delivery_id JOIN biz_products p ON p.id=d.product_id WHERE d.client_id=? AND s.day BETWEEN ? AND ? AND s.invoice_id IS NULL'.($delivery?' AND d.batch_key='.db()->quote($delivery):'')." ORDER BY p.id,s.id",[$client,$start,$end])->fetchAll();
 $rows=array_values(array_filter($rows,fn($r)=>($c['code']==='PT'&&$kind==='consigned')||($kind==='direct'?!bizConsigned((string)$c['code'],$r['category']):bizConsigned((string)$c['code'],$r['category']))));if(!$rows)throw new InvalidArgumentException('정산할 미청구 판매가 없습니다.');
 $lines=[];$net=$tax=$discount=0;foreach($rows as $r)if($r['hst_bp']===null)throw new InvalidArgumentException('상품의 HST를 먼저 지정하세요.');
 foreach($rows as $r){$bp=$c['code']==='OK'&&$r['category']!=='kimchi'?2000:(int)$r['discount_bp'];$key=$r['category'].'|'.$r['hst_bp'].'|'.$r['en'].'|'.$r['pack'].'|'.$r['cents'].'|'.$bp;if(!isset($lines[$key]))$lines[$key]=['category'=>$r['category'],'tax_bp'=>(int)$r['hst_bp'],'ko'=>$r['ko'],'en'=>$r['en'],'pack'=>'','qty'=>0,'base'=>0,'staff'=>0,'unit'=>(int)$r['cents'],'bp'=>$bp,'taxable'=>(int)$r['hst_bp']>0,'discount'=>0,'net'=>0,'hst'=>0];$lines[$key]['qty']+=(int)$r['qty'];$lines[$key]['base']+=$r['gross_cents']===null?(int)$r['qty']*(int)$r['cents']:(int)$r['gross_cents'];$lines[$key]['staff']+=(int)$r['staff_qty'];}
 $taxable=0;foreach($lines as &$l){$base=$l['base'];$l['unit']=$base%$l['qty']===0?intdiv($base,$l['qty']):null;$cut=(int)round($base*$l['bp']/10000);$l['discount']=$cut;$l['net']=$base-$cut;$discount+=$cut;$net+=$l['net'];if($l['taxable']){$taxable+=$l['net'];$nextTax=(int)round($taxable*13/100);$l['hst']=$nextTax-$tax;$tax=$nextTax;}}unset($l);
 if($staffCount){if($c['code']!=='PT'||$kind!=='consigned')throw new InvalidArgumentException('Staff Purchases는 Popularitea 월 정산에만 적용합니다.');$eligible=array_sum(array_map(fn($l)=>$l['taxable']?$l['qty']:0,$lines));$deduction=$staffCount*$staffUnit;if($deduction>$taxable)throw new InvalidArgumentException('직원 차감액이 해당 기간의 과세 판매금액을 넘습니다.');$newTax=(int)round(($taxable-$deduction)*13/100);$lines['staff']=['ko'=>'직원 판매 차감','en'=>'Staff Purchases','pack'=>'','qty'=>$staffCount,'unit'=>-$staffUnit,'discount'=>0,'net'=>-$deduction,'hst'=>$newTax-$tax];$net-=$deduction;$discount+=$deduction;$tax=$newTax;}
 if(count($lines)>34)throw new InvalidArgumentException('한 페이지에 담을 품목이 너무 많습니다. 기간을 나누어 발행하세요.');
 $seller=query('SELECT * FROM biz_settings WHERE id=1')->fetch();if(!$seller['address']||!$seller['gst'])throw new InvalidArgumentException('인보이스 발행 전에 사업자 주소와 GST/HST 번호를 등록하세요.');
 $snapshot=['client'=>$c,'seller'=>$seller,'lines'=>array_values($lines),'net'=>$net,'hst'=>$tax,'discount'=>$discount,'total'=>$net+$tax];
 query('INSERT INTO biz_invoices (client_id,issued,period_start,period_end,kind,snapshot,total_cents,created_by,mail_state) VALUES (?,?,?,?,?,?,?,?,?)',[$client,date('Y-m-d'),$start,$end,$kind,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$net+$tax,$_SESSION['user_id']??null,in_array($c['code'],['OK','PT'])?'pending':'manual']);$id=(int)db()->lastInsertId();
 foreach($rows as $r)query('UPDATE biz_sales SET invoice_id=? WHERE id=? AND invoice_id IS NULL',[$id,$r['id']]);
 if($delivery===null)query('INSERT INTO biz_periods VALUES (?,?,?,?,?)',[$client,$kind,$start,$end,$id]);return $id;
}
function bizAction(string $action): never {
 $next='biz';db()->beginTransaction();try{
 if(($workflowNext=bizWorkflowAction($action))!==null){$next=$workflowNext;}
 elseif($action==='biz_catalog_save'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$p=query('SELECT * FROM biz_products WHERE id=? AND active=1 FOR UPDATE',[$id])->fetch();if(!$p)throw new InvalidArgumentException('제품을 확인하세요.');$retail=textfield($_POST,'retail',20);query('UPDATE biz_products SET ko=?,en=?,retail_cents=? WHERE id=?',[textfield($_POST,'ko',100,true),textfield($_POST,'en',100,true),$retail===''?null:cents($retail),$id]);foreach(query('SELECT id FROM biz_clients WHERE code IS NOT NULL')->fetchAll(PDO::FETCH_COLUMN) as $cid){$v=textfield($_POST,'price_'.$cid,20);if($v==='')query('DELETE FROM biz_prices WHERE client_id=? AND product_id=?',[$cid,$id]);else query('INSERT INTO biz_prices VALUES (?,?,?) ON DUPLICATE KEY UPDATE cents=VALUES(cents)',[$cid,$id,cents($v)]);}$next='biz-products&edit='.$id.'#product-'.$id;}
 elseif($action==='biz_plan_update'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$d=query('SELECT * FROM biz_deliveries WHERE id=? FOR UPDATE',[$id])->fetch();if(!$d||$d['sent']||$d['cancelled']||(int)$d['version']!==(int)($_POST['version']??0))throw new InvalidArgumentException('다른 화면에서 변경되었거나 이미 납품한 계획입니다.');$q=positiveInt($_POST['planned']??0,0,10000);query('UPDATE biz_deliveries SET planned=?,cancelled=?,version=version+1 WHERE id=?',[$q,$q===0?1:0,$id]);query('UPDATE biz_orders SET manual_edited=1,version=version+1 WHERE batch_key=?',[$d['batch_key']]);if(!bizBatchPending($d['batch_key'])&&!bizBatchSent($d['batch_key']))query('UPDATE biz_orders SET cancelled=1 WHERE batch_key=?',[$d['batch_key']]);$next='biz-deliveries';}
 elseif($action==='biz_deliver'){$next=bizShip(positiveInt($_POST['id']??0,1,PHP_INT_MAX),positiveInt($_POST['delivered']??0,1,10000),isset($_POST['discount'])?bizRate($_POST['discount']):null);}
 elseif($action==='biz_result'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$d=query('SELECT d.*,p.category,p.ko,p.en,p.pack,p.retail_cents FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.id=? AND d.sent=1 FOR UPDATE',[$id])->fetch();if(!$d)throw new InvalidArgumentException('납품을 확인하세요.');$c=query('SELECT * FROM biz_clients WHERE id=?',[$d['client_id']])->fetch();if(!bizConsigned((string)$c['code'],$d['category']))throw new InvalidArgumentException('직매출은 납품 시 기록합니다.');$day=validDate(textfield($_POST,'day',10,true));if($day<$d['day'])throw new InvalidArgumentException('판매일은 납품일 이후여야 합니다.');bizClosed((int)$c['id'],$day);$q=positiveInt($_POST['sold']??0,0,10000);$back=positiveInt($_POST['returned']??0,0,10000);$staff=0;if((int)($_POST['staff']??0)!==0)throw new InvalidArgumentException('직원 수량은 월 인보이스의 Staff Purchases에 입력하세요.');if($q+$back>bizAvailable($id))throw new InvalidArgumentException('판매·반품 수량이 남은 재고보다 많습니다.');$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');if(query('SELECT id FROM biz_sales WHERE request_key=? UNION SELECT id FROM biz_returns WHERE request_key=?',[$key,$key])->fetch())throw new InvalidArgumentException('이미 기록했습니다.');if($q)query('INSERT INTO biz_sales (delivery_id,day,qty,staff_qty,cents,request_key,gross_cents) VALUES (?,?,?,?,?,?,?)',[$id,$day,$q,$staff,bizPrice($c,[...$d,'id'=>$d['product_id']]),$key,bizSaleGross($d,$q)]);if($back)query('INSERT INTO biz_returns (delivery_id,day,qty,request_key) VALUES (?,?,?,?)',[$id,$day,$back,$key]);query('INSERT INTO biz_reports VALUES (?,?,?) ON DUPLICATE KEY UPDATE day=day',[$c['id'],$id,$day]);$next='biz-results';}
 elseif($action==='biz_settle'){if(query('SELECT code FROM biz_clients WHERE id=?',[(int)($_POST['client_id']??0)])->fetchColumn()==='PT'&&($_POST['staff_confirm']??'')!=='yes')throw new InvalidArgumentException('Popularitea 직원 판매 통보를 받은 뒤 확인란에 체크하세요.');require_once __DIR__.'/business-mail.php';$checkClient=positiveInt($_POST['client_id']??0,1,PHP_INT_MAX);$checkStart=validDate(textfield($_POST,'start',10,true));$checkEnd=validDate(textfield($_POST,'end',10,true));if(!bizReportsComplete($checkClient,$checkStart,$checkEnd))throw new InvalidArgumentException('기간 내 일일 판매·0개 판매·반품 마감을 먼저 완료하세요.');$id=bizIssue(positiveInt($_POST['client_id']??0,1,PHP_INT_MAX),validDate(textfield($_POST,'start',10,true)),validDate(textfield($_POST,'end',10,true)),'consigned',null,positiveInt($_POST['staff_count']??0,0,100000),cents($_POST['staff_unit']??'1.50'));$next='biz-invoice&id='.$id;}
 elseif($action==='biz_payment'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$i=query('SELECT * FROM biz_invoices WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i)throw new InvalidArgumentException('인보이스를 확인하세요.');$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');if(!query('SELECT id FROM biz_payments WHERE request_key=?',[$key])->fetch()){$amount=cents($_POST['amount']??'');$paid=(int)query('SELECT COALESCE(SUM(cents),0) FROM biz_payments WHERE invoice_id=?',[$id])->fetchColumn();if(!$amount||$paid+$amount>(int)$i['total_cents'])throw new InvalidArgumentException('남은 금액을 확인하세요.');$method=textfield($_POST,'method',20,true);if(!in_array($method,['cash','etransfer'],true))throw new InvalidArgumentException('수금 방법을 확인하세요.');query('INSERT INTO biz_payments (invoice_id,day,cents,method,request_key,created_by) VALUES (?,?,?,?,?,?)',[$id,validDate(textfield($_POST,'day',10,true)),$amount,$method,$key,$_SESSION['user_id']]);}$next=($_POST['return_to']??'')==='collections'?'biz-collections':'biz-invoice&id='.$id;}
 elseif($action==='biz_queue'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$i=query('SELECT * FROM biz_invoices WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i||$i['mail_state']==='sending')throw new InvalidArgumentException('인보이스 또는 현재 발송 상태를 확인하세요.');query("UPDATE biz_invoices SET mail_state='pending',mail_error='' WHERE id=?",[$id]);$next='biz-invoice&id='.$id;}
 elseif($action==='biz_settings'){$email=textfield($_POST,'email',150);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('발신 이메일을 확인하세요.');query('UPDATE biz_settings SET seller=?,address=?,gst=?,email=? WHERE id=1',[textfield($_POST,'seller',150,true),textfield($_POST,'address',500),textfield($_POST,'gst',100),$email]);$next='biz-clients';}
 else throw new InvalidArgumentException('업무를 확인하세요.');
 query('INSERT INTO biz_events (actor_id,kind,detail) VALUES (?,?,?)',[$_SESSION['user_id'],$action,json_encode(['input'=>array_diff_key($_POST,['csrf'=>1])],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);db()->commit();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
 $_SESSION['flash']='저장했습니다.';redirect('/?page='.$next);
}
